.hk-card[data-theme="dark"]{--hk-surface:var(--ha-card-background,var(--card-background-color,#252422));--hk-raised:#302f2c;--hk-ink:var(--primary-text-color,#f3f0e9);--hk-muted:var(--secondary-text-color,rgba(244,241,234,.62));--hk-line:var(--divider-color,rgba(244,241,234,.13));--hk-fill:rgba(244,241,234,.09);--hk-green:#52ba72;--hk-orange:#ee9d43;--hk-red:#ed625b;box-shadow:0 19px 50px rgba(0,0,0,.3),inset 0 1px rgba(255,255,255,.055)}
.hk-card button,.hk-card input,.hk-card select{font:inherit}.hk-card button{-webkit-tap-highlight-color:transparent}.hk-card button:focus-visible,.hk-card input:focus-visible,.hk-card select:focus-visible{outline:2px solid color-mix(in srgb,var(--hk-accent) 78%,#4d8fe8);outline-offset:2px}
.hk-kicker{display:block;color:var(--hk-muted);font-size:9px;font-weight:760;letter-spacing:.13em;text-transform:uppercase}.hk-name{display:block;overflow:hidden;font-size:clamp(17px,8cqh,23px);font-weight:700;letter-spacing:-.04em;text-overflow:ellipsis;white-space:nowrap}.hk-state{display:block;overflow:hidden;color:var(--hk-muted);font-size:11px;font-weight:540;text-overflow:ellipsis;white-space:nowrap}
.hk-primary{display:grid;place-items:center;width:46px;height:46px;padding:0;border:0;border-radius:50%;color:var(--hk-muted);background:var(--hk-fill);cursor:pointer;transition:transform 140ms ease,background-color 180ms ease,color 180ms ease}.hk-primary:active{transform:scale(.9)}.hk-primary ha-icon{--mdc-icon-size:23px}.hk-settings{position:absolute;z-index:12;top:9px;right:9px;width:31px;height:31px;display:grid;place-items:center;padding:0;border:0;border-radius:50%;color:var(--hk-muted);background:color-mix(in srgb,var(--hk-raised) 72%,transparent);cursor:pointer;opacity:.16;transition:opacity 150ms ease,transform 150ms ease}.hk-card:hover .hk-settings,.hk-settings:focus-visible{opacity:1}.hk-settings:active{transform:scale(.9)}.hk-settings ha-icon{--mdc-icon-size:17px}
