.hk-climate{display:grid;grid-template-columns:45% minmax(0,1fr);align-items:center;padding:15px 17px;background:color-mix(in srgb,var(--hk-accent) 5%,var(--hk-surface))}.hkc-dial{position:relative;width:min(145px,72cqh);aspect-ratio:1;display:grid;place-items:center;justify-self:center;padding:0;border:0;border-radius:50%;color:inherit;background:color-mix(in srgb,var(--hk-raised) 88%,transparent);box-shadow:0 12px 30px rgba(55,47,38,.11),inset 0 1px rgba(255,255,255,.7);cursor:pointer}.hkc-dial svg{position:absolute;inset:8%;width:84%;height:84%;transform:rotate(-90deg)}.hkc-dial circle{fill:none;stroke:color-mix(in srgb,var(--hk-ink) 8%,transparent);stroke-width:7}.hkc-dial .hkc-value{stroke:var(--hk-accent);stroke-linecap:round;stroke-dasharray:var(--hkc-progress,50) 100;transition:stroke-dasharray 280ms cubic-bezier(.22,1,.36,1)}.hkc-dial>span{display:grid;justify-items:center;gap:1px}.hkc-dial small{color:var(--hk-muted);font-size:10px}.hkc-dial strong{font-size:clamp(27px,14cqh,40px);font-weight:650;letter-spacing:-.065em}.hkc-copy{min-width:0;display:grid;align-content:center;gap:3px;padding:8px 30px 8px 15px}.hkc-adjust{display:grid;grid-template-columns:33px minmax(0,1fr) 33px;align-items:center;gap:6px;margin-top:12px}.hkc-adjust button{height:33px;padding:0;border:0;border-radius:50%;color:var(--hk-ink);background:var(--hk-fill);font-size:19px;cursor:pointer}.hkc-adjust span{overflow:hidden;color:var(--hk-muted);font-size:9px;text-align:center;text-overflow:ellipsis;white-space:nowrap}.hkc-power{position:absolute;left:18px;bottom:15px;width:38px;height:38px}.hkc-power ha-icon{--mdc-icon-size:18px}.hk-climate[data-active="true"] .hkc-power{color:color-mix(in srgb,var(--hk-accent) 82%,var(--hk-ink));background:color-mix(in srgb,var(--hk-accent) 17%,transparent)}.hk-climate[data-layout="compact"]{grid-template-columns:1fr;padding:10px}.hk-climate[data-layout="compact"] .hkc-dial{width:123px}.hk-climate[data-layout="compact"] .hkc-copy{position:absolute;left:15px;right:15px;bottom:12px;display:block;padding:0}.hk-climate[data-layout="compact"] .hkc-copy>.hk-kicker,.hk-climate[data-layout="compact"] .hkc-copy>.hk-name,.hk-climate[data-layout="compact"] .hkc-copy>.hk-state{display:none}.hk-climate[data-layout="compact"] .hkc-adjust{margin:0}.hk-climate[data-layout="compact"] .hkc-power{left:13px;top:13px;bottom:auto}.hk-climate[data-layout="micro"]{grid-template-columns:100px 1fr;padding:7px 12px}.hk-climate[data-layout="micro"] .hkc-dial{width:88px}.hk-climate[data-layout="micro"] .hkc-copy{padding:4px 35px 4px 8px}.hk-climate[data-layout="micro"] .hkc-adjust,.hk-climate[data-layout="micro"] .hkc-power,.hk-climate[data-layout="micro"] .hk-settings{display:none}

